-- These CHECK constraints were first generated by Hibernate from an older enum set and only
-- allowed PENDING/IN_PROGRESS/COMPLETED. Cancelling a session (cancel, remove dish, heartbeat
-- sweep) writes CANCELLED and failed with:
--   violates check constraint "session_dishes_status_check"
-- ddl-auto=update never rewrites an existing check constraint, so widen them explicitly here.
DO $$
BEGIN
    IF to_regclass('cooking_sessions') IS NOT NULL THEN
        ALTER TABLE cooking_sessions
            DROP CONSTRAINT IF EXISTS cooking_sessions_status_check;

        ALTER TABLE cooking_sessions
            ADD CONSTRAINT cooking_sessions_status_check
            CHECK (status IN ('ACTIVE', 'COMPLETED', 'CANCELLED'));
    END IF;

    IF to_regclass('session_dishes') IS NOT NULL THEN
        ALTER TABLE session_dishes
            DROP CONSTRAINT IF EXISTS session_dishes_status_check;

        ALTER TABLE session_dishes
            ADD CONSTRAINT session_dishes_status_check
            CHECK (status IN ('PENDING', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED'));
    END IF;

    IF to_regclass('session_dish_steps') IS NOT NULL THEN
        ALTER TABLE session_dish_steps
            DROP CONSTRAINT IF EXISTS session_dish_steps_status_check;

        ALTER TABLE session_dish_steps
            ADD CONSTRAINT session_dish_steps_status_check
            CHECK (status IN ('PENDING', 'IN_PROGRESS', 'TIMER_RUNNING',
                              'TIMER_COMPLETED_AWAITING_USER', 'COMPLETED', 'CANCELLED'));
    END IF;
END;
$$;
